"""E058 inventories of the benchmark trees (git ls-tree of every base commit).

    E058-inventory.py suffix .suffix1,.suffix2 SPLIT [SPLIT ...]   # files and tasks per suffix
    E058-inventory.py env SPLIT [SPLIT ...]                         # tasks with env/venv directories
"""
import sys

if sys.argv[1] == 'suffix':
    sys.argv = [sys.argv[0]] + sys.argv[2:]
    exec(compile('"""Files of the given suffixes at each task\'s base commit: per split, files and tasks (and repos) affected."""\nimport collections\nimport os\nimport subprocess\nimport sys\n\nsys.path.insert(0, os.getcwd())\nos.environ.setdefault("NPK_BENCH_HOME", "/home/user/npk-data")\nfrom benchmarks.npkbench import data, repos\n\nSUFFIXES = tuple(sys.argv[1].split(","))\nfor split in sys.argv[2:]:\n    tasks = data.split(split)\n    cache, hits, tasks_with, repos_with = {}, collections.Counter(), collections.defaultdict(set), collections.defaultdict(collections.Counter)\n    for t in tasks:\n        key = (t.repo, t.base_commit)\n        if key not in cache:\n            names = subprocess.run(["git", "-C", str(repos.clone_dir(t.repo)), "ls-tree", "-r", "--name-only", t.base_commit],\n                                   capture_output=True, text=True).stdout.splitlines()\n            cache[key] = collections.Counter(os.path.splitext(n)[1].lower() for n in names if n.lower().endswith(SUFFIXES))\n        for suf, n in cache[key].items():\n            hits[suf] += 1\n            tasks_with[suf].add(t.instance_id)\n            repos_with[suf][t.repo] += 1\n    print(f"{split}: {len(tasks)} tasks;", {s: len(tasks_with[s]) for s in SUFFIXES if tasks_with[s]} or "none", "(tasks with such files)")\n    for suf in SUFFIXES:\n        if tasks_with[suf]:\n            print("    ", suf, dict(repos_with[suf].most_common(6)))\n', 'suffix_inventory', 'exec'))
else:
    sys.argv = [sys.argv[0]] + sys.argv[2:]
    exec(compile('"""Tasks whose base-commit tree has a directory named env or venv (the E058 env/venv rule applies)."""\nimport collections\nimport os\nimport subprocess\nimport sys\n\nsys.path.insert(0, os.getcwd())\nos.environ.setdefault("NPK_BENCH_HOME", "/home/user/npk-data")\nfrom benchmarks.npkbench import data, repos\n\nfor split in sys.argv[1:]:\n    tasks = data.split(split)\n    cache, per_repo = {}, collections.defaultdict(collections.Counter)\n    affected = set()\n    for t in tasks:\n        key = (t.repo, t.base_commit)\n        if key not in cache:\n            names = subprocess.run(["git", "-C", str(repos.clone_dir(t.repo)), "ls-tree", "-r", "--name-only", t.base_commit],\n                                   capture_output=True, text=True).stdout.splitlines()\n            dirs = collections.Counter()\n            for n in names:\n                parts = n.split("/")\n                for i, part in enumerate(parts[:-1]):\n                    if part in ("env", "venv") and not any(q.startswith(".") for q in parts[:i]):\n                        dirs["/".join(parts[:i + 1])] += 1\n            cache[key] = dirs\n        if cache[key]:\n            affected.add(t.instance_id)\n            for d, n in cache[key].items():\n                per_repo[t.repo][d] += 0\n                per_repo[t.repo][d] = max(per_repo[t.repo][d], n)\n    print(f"{split}: {len(tasks)} tasks, {len(affected)} with env/venv directories")\n    for repo, dirs in per_repo.items():\n        print("   ", repo, dict(list(dirs.items())[:5]))\n', 'env_inventory', 'exec'))
